Click to expand...
Try this - for kicks. Lol. (Untested)
Edit: I'm guessing the equal key code is either 61 or 187. You can put that in separately to test.
JavaScript:
(($) => {
    const str  = (x) => String.fromCharCode(x);
    for (let i = 48; i < 58; i++) $[i] = str(i);
    for (let j = 65; j < 90; j++) $[j] = str(j).toLowerCase();
    for (const k of [219, 221]  ) $[k] = str(k - 128);
    $[187] = '=';
    $[189] = '-';
})(Input.keyMapper);
Edit: And one more for variation because I like for-of and I just realized you had some keys not included:
JavaScript:
(($) => {
    const key = '0123456789ABCDEFGHIJKLMNOPRSTUVY=-[]';
    const val = (n) =>
        ['[',']'].includes(n) ? 128 :
                     n == '=' ? 126 :
                     n == '-' ? 144 : 0;
    for (const x of key) {
        const y = key.charCodeAt(key.indexOf(x)) + val(x);
        $[y]    = x.toLowerCase();
    }
})(Input.keyMapper);
